var Q10 = [
{n:1, q:'El primer paso de una unión económica y política de los países europeos se produce en los años 50 a través de:', o:{a:'La Comunidad Europea Minera.',b:'El Tratado de Maastricht.',c:'La Comunidad Europea del Carbón y del Acero.',d:'Ninguna de las respuestas es correcta.'}, correct:'c', why:{c:'El primer paso fue la CECA (Comunidad Europea del Carbón y del Acero), creada por el Tratado de París de 1951.'}},
{n:2, q:'La Comunidad Europea del Carbón y del Acero fue fundada:', o:{a:'Con el Tratado de Roma de 1957.',b:'Con el Tratado de París de 1951.',c:'Con el Tratado de Niza de 1950.',d:'Con el Tratado de Berlín de 1966.'}, correct:'b', why:{b:'La CECA fue creada por el Tratado de París, firmado el 18 de abril de 1951.'}},
{n:3, q:'La Comunidad Europea del Carbón y del Acero la fundaron seis países, entre los que se encontraban:', o:{a:'Alemania, Italia y Francia.',b:'Francia, Reino Unido y Austria.',c:'Bélgica, Luxemburgo y los Países Bajos.',d:'Los citados en las respuestas a y c.'}, correct:'d', why:{d:'Los seis fundadores fueron Francia, Alemania, Italia, Bélgica, Países Bajos y Luxemburgo.'}},
{n:4, q:'La primera unión de países europeos:', o:{a:'Se produce en 1948.',b:'Se denominó EURATOM.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La primera unión de integración económica entre países europeos se produce en los años 40-50.'}},
{n:5, q:'La primera unión de países europeos:', o:{a:'La integran Bélgica, Países Bajos y Luxemburgo.',b:'Se denominó Benelux.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Benelux (Bélgica, Países Bajos y Luxemburgo) fue una de las primeras uniones económicas europeas, precedente de la CEE.'}},
{n:6, q:'El Tratado de Roma se firmó en el año:', o:{a:'1948.',b:'1957.',c:'1961.',d:'1970.'}, correct:'b', why:{b:'El Tratado de Roma fue firmado el 25 de marzo de 1957, creando la CEE y EURATOM.'}},
{n:7, q:'De los siguientes indique el país que no formaba parte del Tratado de Roma:', o:{a:'Francia.',b:'Italia.',c:'Luxemburgo.',d:'Irlanda.'}, correct:'d', why:{d:'Irlanda no firmó el Tratado de Roma; se adhirió en 1973. Los fundadores fueron Francia, Alemania, Italia, Bélgica, Países Bajos y Luxemburgo.'}},
{n:8, q:'No formaba parte del Tratado de Roma de 1957:', o:{a:'Dinamarca.',b:'Austria.',c:'Irlanda.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Dinamarca, Austria e Irlanda NO formaban parte del Tratado de Roma. Los firmantes eran los seis países fundadores.'}},
{n:9, q:'De los siguientes indique el país que formaba parte del Tratado de Roma de 1957:', o:{a:'Bélgica.',b:'Holanda.',c:'Alemania Federal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Bélgica, Países Bajos (Holanda) y Alemania Occidental eran miembros fundadores del Tratado de Roma.'}},
{n:10, q:'El Acta Única Europea es del año:', o:{a:'1987.',b:'1995.',c:'1986.',d:'1992.'}, correct:'a', why:{a:'El Acta Única Europea fue firmada en 1986 y entró en vigor el 1 de julio de 1987.'}},
{n:11, q:'La Unión Europea se constituye formalmente con la firma...', o:{a:'Del Tratado de Niza.',b:'Del Tratado de Ámsterdam.',c:'Del Tratado de Lisboa.',d:'Del Tratado de Maastricht.'}, correct:'d', why:{d:'La UE se constituyó formalmente con el Tratado de Maastricht, firmado el 7 de febrero de 1992.'}},
{n:12, q:'El Tratado de Maastricht se firma el...', o:{a:'11/01/1992.',b:'07/02/1992.',c:'25/03/1992.',d:'30/06/1992.'}, correct:'b', why:{b:'El Tratado de Maastricht fue firmado el 7 de febrero de 1992.'}},
{n:13, q:'El Tratado de Maastricht entró en vigor el...', o:{a:'01/11/1993.',b:'01/01/1993.',c:'11/11/1993.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El Tratado de Maastricht entró en vigor el 1 de noviembre de 1993.'}},
{n:14, q:'El Tratado de Ámsterdam se firmó...', o:{a:'El 02/10/1997.',b:'El 14/05/1998.',c:'El 13/03/1999.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El Tratado de Ámsterdam fue firmado el 2 de octubre de 1997.'}},
{n:15, q:'El Tratado de Ámsterdam entró en vigor...', o:{a:'El 12/12/1998.',b:'El 14/01/1999.',c:'El 01/01/1999.',d:'El 01/05/1999.'}, correct:'d', why:{d:'El Tratado de Ámsterdam entró en vigor el 1 de mayo de 1999.'}},
{n:16, q:'El Tratado de Niza se firmó en...', o:{a:'26/05/2000.',b:'26/02/2001.',c:'24/06/2000.',d:'24/06/2001.'}, correct:'b', why:{b:'El Tratado de Niza fue firmado el 26 de febrero de 2001.'}},
{n:17, q:'El Tratado de Niza entró en vigor el...', o:{a:'01/01/2003.',b:'01/02/2003.',c:'01/03/2003.',d:'01/04/2003.'}, correct:'d', why:{d:'El Tratado de Niza entró en vigor el 1 de febrero de 2003.'}},
{n:18, q:'El Tratado de Lisboa se firmó el:', o:{a:'11/01/2008.',b:'01/01/2008.',c:'13/12/2007.',d:'11/11/2007.'}, correct:'c', why:{c:'El Tratado de Lisboa fue firmado el 13 de diciembre de 2007.'}},
{n:19, q:'El Tratado de Lisboa entró en vigor:', o:{a:'El 1 de enero de 2010.',b:'El 1 de junio de 2009.',c:'El 1 de diciembre de 2009.',d:'Todas las respuestas anteriores son falsas.'}, correct:'c', why:{c:'El Tratado de Lisboa entró en vigor el 1 de diciembre de 2009.'}},
{n:20, q:'En 1973 ingresa en la Comunidad Económica Europea:', o:{a:'Dinamarca.',b:'Irlanda.',c:'Reino Unido.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'En 1973 se incorporaron a la CEE Dinamarca, Irlanda y el Reino Unido.'}},
{n:21, q:'En 1981 ingresa en la Comunidad Económica Europea:', o:{a:'España.',b:'Portugal.',c:'Irlanda.',d:'Grecia.'}, correct:'d', why:{d:'Grecia ingresó en la CEE el 1 de enero de 1981.'}},
{n:22, q:'En 1986 ingresa en la Comunidad Económica Europea:', o:{a:'Irlanda.',b:'España.',c:'Grecia.',d:'Suecia.'}, correct:'b', why:{b:'España y Portugal ingresaron en la CEE el 1 de enero de 1986.'}},
{n:23, q:'En 1995 ingresa en la Comunidad Económica Europea:', o:{a:'Dinamarca.',b:'Finlandia.',c:'Irlanda.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'En 1995 se incorporaron a la UE Austria, Finlandia y Suecia.'}},
{n:24, q:'La República Checa ingresa en la Unión Europea:', o:{a:'En 1986.',b:'En 2004.',c:'En 1992.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'La República Checa ingresó en la UE el 1 de mayo de 2004.'}},
{n:25, q:'Actualmente forman parte de la Unión Europea:', o:{a:'29 Estados.',b:'28 Estados.',c:'27 Estados.',d:'26 Estados.'}, correct:'c', why:{c:'Tras el Brexit (31 enero 2020), la UE está integrada por 27 Estados miembros.'}},
{n:26, q:'El último país que ingresa en la unión Europea es Croacia, y lo hace en el año:', o:{a:'2013.',b:'2009.',c:'2007.',d:'2004.'}, correct:'a', why:{a:'Croacia se incorporó a la UE el 1 de julio de 2013, como el 28º Estado miembro.'}},
{n:27, q:'Reino Unido solicitó su salida de la Unión Europea...', o:{a:'Invocando el artículo 50 del Tratado de la Unión.',b:'El 29 de marzo de 2018.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Reino Unido invocó el art.50 TUE el 29 de marzo de 2017 para iniciar el Brexit.'}},
{n:28, q:'El acuerdo por el que Reino Unido abandona la Unión Europea entró en vigor...', o:{a:'El 01/01/2020.',b:'El 15/01/2020.',c:'El 31/01/2020.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El Brexit entró en vigor el 31 de enero de 2020.'}},
{n:29, q:'La ciudadanía de la Unión Europea:', o:{a:'Sustituye a la nacional en los casos y forma determinados en los Tratados.',b:'Es una ciudadanía ficticia que no puede acreditarse documentalmente.',c:'Obliga a los Estados integrantes de la Unión a adaptar sus legislaciones.',d:'Se añade a la ciudadanía nacional, sin sustituirla.'}, correct:'d', why:{d:'El art.20 TFUE establece que la ciudadanía de la UE se añade a la nacional sin sustituirla.'}},
{n:30, q:'Ciudadano de la Unión Europea es:', o:{a:'Toda persona que resida en un Estado miembro de la Unión.',b:'Toda persona que tenga la nacionalidad de un estado miembro de la Unión.',c:'Toda persona que teniendo la nacionalidad de un estado miembro resida efectivamente.',d:'Cualquier persona que resida legalmente en un Estado miembro por más de seis meses.'}, correct:'b', why:{b:'El art.20 TFUE establece que es ciudadano de la UE toda persona que tenga la nacionalidad de un Estado miembro.'}},
{n:31, q:'El funcionamiento de la Unión Europea está basado en:', o:{a:'La democracia participativa.',b:'La Jerarquía normativa.',c:'La democracia social y de derecho.',d:'La democracia representativa.'}, correct:'c', why:{c:'El art.10 TUE establece que el funcionamiento de la UE se basa en la democracia representativa.'}},
{n:32, q:'Las relaciones de la Unión Europea con los Estados miembros se rigen por el principio de:', o:{a:'Competencia.',b:'Jerarquía.',c:'Descentralización.',d:'Desconcentración.'}, correct:'a', why:{a:'Las relaciones entre la UE y los Estados miembros se rigen por el principio de atribución de competencias.'}},
{n:33, q:'La Unión Europea tiene competencia exclusiva en materia de:', o:{a:'Medio ambiente.',b:'Agricultura.',c:'Pesca.',d:'Unión Aduanera.'}, correct:'d', why:{d:'El art.3 TFUE establece competencia exclusiva de la UE en la Unión Aduanera, entre otras.'}},
{n:34, q:'El principio por el cual la Unión Europea intervendrá solo en el caso de que los objetivos pretendidos no puedan ser alcanzados de manera suficiente por los Estados miembros recibe el nombre de:', o:{a:'Principio de atribución.',b:'Principio de subsidiariedad.',c:'Principio de mínima intervención.',d:'Principio de proporcionalidad.'}, correct:'b', why:{b:'El principio de subsidiariedad (art.5.3 TUE) limita la intervención de la UE a cuando los objetivos no puedan alcanzarse suficientemente por los Estados miembros.'}},
{n:35, q:'El principio por el cual, el contenido y la forma de acción de la Unión Europea no excederán de lo necesario para alcanzar los objetivos de los Tratados, se conoce con el nombre de:', o:{a:'Principio de proporcionalidad.',b:'Principio de atribución.',c:'Principio de mínima intervención.',d:'Principio de subsidiariedad.'}, correct:'a', why:{a:'El principio de proporcionalidad (art.5.4 TUE) exige que la acción de la UE no exceda de lo necesario para alcanzar sus objetivos.'}},
{n:36, q:'En aquellos ámbitos que no sean de su competencia exclusiva, la Unión Europea intervendrá solo en el caso de que los objetivos pretendidos no puedan ser alcanzados de manera suficiente por los estados miembros. Esto se conoce como:', o:{a:'Principio de atribución.',b:'Principio de subsidiariedad.',c:'Principio de mínima intervención.',d:'Principio de proporcionalidad.'}, correct:'b', why:{b:'Es la definición del principio de subsidiariedad (art.5.3 TUE).'}},
{n:37, q:'La Unión Europea tiene competencia exclusiva en materia de:', o:{a:'Política comercial común.',b:'Protección de consumidores.',c:'Asuntos comunes de seguridad en materia de salud pública.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'La política comercial común es competencia exclusiva de la UE (art.3 TFUE). La protección de consumidores y la salud pública son competencias compartidas.'}},
{n:38, q:'Respecto de las competencias, indique cual de las siguientes es compartida entre los Estados miembros y la Unión Europea:', o:{a:'Conservación de recursos biológicos marinos dentro de la política pesquera común.',b:'Cohesión económica, social y territorial.',c:'Política comercial común.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La cohesión económica, social y territorial es competencia compartida entre la UE y los Estados miembros (art.4 TFUE).'}},
{n:39, q:'No es una institución de la Unión Europea:', o:{a:'El Parlamento Europeo.',b:'La Comisión Europea.',c:'El Consejo de Europa.',d:'Todas las anteriores son instituciones de la Unión Europea.'}, correct:'d', why:{d:'El Consejo de Europa NO es una institución de la UE; es una organización internacional independiente. Las instituciones de la UE son el PE, Consejo Europeo, Consejo, Comisión, TJUE, BCE y Tribunal de Cuentas.'}},
{n:40, q:'Es una institución de la Unión Europea:', o:{a:'El Parlamento Europeo.',b:'El Consejo Europeo.',c:'El Consejo de la Unión Europea.',d:'Todas las anteriores son instituciones de la Unión Europea.'}, correct:'d', why:{d:'El PE, el Consejo Europeo y el Consejo de la UE son todas instituciones de la UE.'}},
{n:41, q:'Los ciudadanos están representados en la Unión Europea por medio de:', o:{a:'La Comisión Europea.',b:'El Consejo Europeo.',c:'El Parlamento Europeo.',d:'El Consejo de la Unión Europea.'}, correct:'c', why:{c:'El art.10 TUE establece que los ciudadanos están directamente representados en la UE a través del PE.'}},
{n:42, q:'El número de miembros del Parlamento Europeo:', o:{a:'No puede exceder de 750, además de su Presidente.',b:'No puede ser inferior a 750.',c:'No puede exceder de 750, incluido su Presidente.',d:'Es de 750.'}, correct:'a', why:{a:'El art.14.2 TUE: el número de miembros del PE no excederá de 750, más el Presidente.'}},
{n:43, q:'Actualmente, el número de miembros del Parlamento Europeo es de:', o:{a:'750.',b:'715.',c:'705.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Tras el Brexit y la redistribución de escaños, el PE tiene 705 miembros (sin contar el Presidente).'}},
{n:44, q:'El número de diputados que representan a España en el Parlamento Europeo es de:', o:{a:'52.',b:'59.',c:'76.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'España tiene 61 escaños en el PE (el dato puede variar según la legislatura; la respuesta correcta según el solucionario es b=59).'}},
{n:45, q:'El número de diputados que representan a Alemania en el Parlamento Europeo es de:', o:{a:'76.',b:'59.',c:'96.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Alemania tiene 96 escaños en el PE, el número máximo permitido por ser el Estado más poblado.'}},
{n:46, q:'El número de diputados que representan a Italia en el Parlamento Europeo es de:', o:{a:'52.',b:'59.',c:'76.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Italia tiene aproximadamente 76 escaños en el PE. El solucionario indica b=59.'}},
{n:47, q:'En el Parlamento Europeo está representada con 21 diputados:', o:{a:'Portugal.',b:'Países Bajos.',c:'Irlanda.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Portugal está representada con 21 escaños en el Parlamento Europeo.'}},
{n:48, q:'En el Parlamento Europeo está representada con 17 diputados:', o:{a:'Chipre.',b:'Rumanía.',c:'Bulgaria.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'Bulgaria está representada con 17 eurodiputados en el Parlamento Europeo.'}},
{n:49, q:'En el Parlamento Europeo está representado con 19 diputados:', o:{a:'Hungría.',b:'Austria.',c:'Bélgica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Hungría, Austria y Bélgica tienen representaciones de entre 19 y 21 escaños en el PE.'}},
{n:50, q:'En el Parlamento Europeo está representado con 11 diputados:', o:{a:'Finlandia.',b:'Letonia.',c:'Dinamarca.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El número exacto de escaños varía; ninguna de las opciones corresponde exactamente a 11 escaños en la legislatura vigente al elaborarse el test.'}},
{n:51, q:'En el Parlamento Europeo está representado con 11 diputados:', o:{a:'Lituania.',b:'Irlanda.',c:'Eslovenia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Lituania tiene aproximadamente 11 escaños en el Parlamento Europeo.'}},
{n:52, q:'En el Parlamento Europeo está representado con 21 diputados:', o:{a:'Chequia.',b:'Croacia.',c:'Grecia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'La República Checa tiene 21 escaños en el Parlamento Europeo.'}},
{n:53, q:'En el Parlamento Europeo está representado con 6 diputados:', o:{a:'Chipre.',b:'Luxemburgo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Chipre y Luxemburgo tienen 6 escaños cada uno en el PE (número mínimo permitido).'}},
{n:54, q:'En el Parlamento Europeo está representado con 8 diputados:', o:{a:'Malta.',b:'Letonia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Letonia tiene aproximadamente 9 escaños en el PE; Malta tiene 6.'}},
{n:55, q:'En el Parlamento Europeo está representado con 14 diputados:', o:{a:'Eslovaquia.',b:'Finlandia.',c:'Dinamarca.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Eslovaquia, Finlandia y Dinamarca tienen entre 13 y 15 escaños cada uno en el PE.'}},
{n:56, q:'En el Consejo de la Unión Europea los Estados están representados:', o:{a:'Directamente por los ciudadanos.',b:'Por sus respectivos Jefes de Estado o de Gobierno.',c:'Por sus respectivos Gobiernos.',d:'Por sus Delegaciones Diplomáticas.'}, correct:'c', why:{c:'El art.16.2 TUE: el Consejo está compuesto por un representante ministerial de cada Estado miembro.'}},
{n:57, q:'Son órganos consultivos de la Unión Europea:', o:{a:'El Consejo y la Comisión.',b:'El Alto representante de la Unión y el Banco Europeo de Inversiones.',c:'El Comité Económico y Social y el Comité de las Regiones.',d:'El Tribunal de Cuentas y el Banco Europeo de Inversiones.'}, correct:'c', why:{c:'El CESE y el Comité de las Regiones son los órganos consultivos de la UE.'}},
{n:58, q:'En el Consejo Europeo, los Estados están representados a través de:', o:{a:'Sus respectivos Jefes de Estado o de Gobierno.',b:'Sus respectivos Ministros de Asuntos Exteriores.',c:'Los representantes elegidos por los ciudadanos en las elecciones europeas.',d:'Sus respectivos Gobiernos.'}, correct:'a', why:{a:'El art.15.2 TUE: el Consejo Europeo está compuesto por los Jefes de Estado o de Gobierno de los Estados miembros.'}},
{n:59, q:'La política monetaria de los Estados cuya moneda es el euro:', o:{a:'Es una competencia exclusiva de la Unión Europea.',b:'Es una competencia compartida por la Unión Europea con los Estados miembros.',c:'No forma parte de las normas de competencias exclusivas de la Unión Europea.',d:'Se rige por las normas establecidas en un Tratado Especial.'}, correct:'a', why:{a:'La política monetaria de los Estados de la zona euro es competencia exclusiva de la UE (art.3 TFUE).'}},
{n:60, q:'Con respecto al Defensor del Pueblo Europeo, indique la respuesta incorrecta:', o:{a:'Es elegido por el Parlamento Europeo para toda la legislatura.',b:'Ejercerá sus funciones con total independencia.',c:'Está facultado para recibir reclamaciones de cualquier ciudadano de la Unión.',d:'Su mandato no es renovable.'}, correct:'b', why:{b:'El mandato del Defensor del Pueblo Europeo SÍ es renovable; la afirmación "su mandato no es renovable" es incorrecta.'}},
{n:61, q:'En el ámbito de la Unión Europea, el órgano encargado de velar y proteger los intereses estrictamente comunitarios es:', o:{a:'El Consejo Europeo.',b:'El Consejo de la Unión Europea.',c:'La Comisión Europea.',d:'El Parlamento Europeo.'}, correct:'c', why:{c:'La Comisión Europea es la guardiana de los Tratados y defiende el interés general de la UE.'}},
{n:62, q:'La sede del Parlamento Europeo está en:', o:{a:'Luxemburgo.',b:'Bruselas.',c:'Estrasburgo.',d:'Maastricht.'}, correct:'c', why:{c:'La sede oficial del Parlamento Europeo está en Estrasburgo.'}},
{n:63, q:'Componen el Consejo Europeo:', o:{a:'Los Jefes de Estado o de Gobierno de los Estados miembros.',b:'El Presidente del Consejo Europeo y el Presidente de la Comisión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.15.2 TUE: el Consejo Europeo está compuesto por los Jefes de Estado o de Gobierno, su Presidente y el Presidente de la Comisión.'}},
{n:64, q:'¿Qué órgano de la Unión Europea, que tiene su sede en Bruselas, en algunos meses del año celebra sus sesiones en Luxemburgo?', o:{a:'La Comisión Europea.',b:'El Consejo de la Unión Europea.',c:'El Consejo Europeo.',d:'El Tribunal de Justicia de la Unión Europea.'}, correct:'b', why:{b:'El Consejo de la UE, con sede en Bruselas, celebra sesiones en Luxemburgo en abril, junio y octubre.'}},
{n:65, q:'El Presidente del Consejo Europeo.', o:{a:'Es elegido para un periodo de 5 años.',b:'No puede renovar su mandato.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El Presidente del Consejo Europeo se elige para un mandato de 2,5 años, renovable una vez.'}},
{n:66, q:'Los diputados del Parlamento Europeo son elegidos por sufragio universal, directo, libre y secreto para un periodo de:', o:{a:'4 años.',b:'5 años.',c:'8 años.',d:'2 años y medio.'}, correct:'b', why:{b:'Los eurodiputados se eligen para un mandato de cinco años.'}},
{n:67, q:'En los trabajos del Consejo Europeo participa:', o:{a:'El Defensor del Pueblo Europeo.',b:'El Presidente del Parlamento Europeo.',c:'El Alto representante de la Unión para Asuntos Exteriores y Política de Seguridad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art.15.2 TUE: el Alto Representante participa en los trabajos del Consejo Europeo.'}},
{n:68, q:'Se reúne dos veces por semestre:', o:{a:'La Comisión Europea.',b:'El Consejo de la Unión Europea.',c:'El Consejo Europeo.',d:'El Tribunal de Cuentas Europeo.'}, correct:'c', why:{c:'El art.15.3 TUE: el Consejo Europeo se reunirá dos veces por semestre.'}},
{n:69, q:'Cada Estado miembro aporta al Parlamento Europeo un número de diputados comprendido entre:', o:{a:'Un mínimo de 9 y un máximo de 69.',b:'Un mínimo de 5 y un máximo de 72.',c:'Un mínimo de 8 y un máximo de 93.',d:'Un mínimo de 6 y un máximo de 96.'}, correct:'d', why:{d:'El art.14.2 TUE: mínimo de 6 y máximo de 96 escaños por Estado miembro.'}},
{n:70, q:'Las Comisiones del Parlamento Europeo se reúnen en:', o:{a:'Estrasburgo.',b:'Luxemburgo.',c:'Bruselas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Las comisiones del PE se reúnen en Bruselas; las sesiones plenarias, en Estrasburgo.'}},
{n:71, q:'El ejercicio de la función legislativa y presupuestaria de la Unión Europea, que el Parlamento realiza de manera conjunta con el Consejo de la Unión y la Comisión, se denomina:', o:{a:'Doble mayoría.',b:'Proceso de decisión conjunta.',c:'Procedimiento legislativo especial.',d:'Procedimiento legislativo ordinario.'}, correct:'c', why:{c:'El procedimiento legislativo ordinario (codecisión, art.294 TFUE) es el ejercicio conjunto de función legislativa por el PE y el Consejo.'}},
{n:72, q:'En el ámbito de la Unión Europea normalmente adopta sus decisiones por consenso:', o:{a:'El Parlamento Europeo.',b:'El Consejo Europeo.',c:'El Consejo de la Unión Europea.',d:'La Comisión Europea.'}, correct:'c', why:{c:'El art.15.4 TUE: el Consejo Europeo se pronunciará por consenso.'}},
{n:73, q:'En caso de presentación de una moción de censura al Parlamento Europeo sobre la gestión de la Comisión:', o:{a:'Deberá pronunciarse sobre ella en los tres días siguientes, mediante votación pública.',b:'Su aprobación precisa de la mayoría de dos tercios de los votos emitidos que representen a la mayoría de los diputados que componen el Parlamento Europeo.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La moción de censura al PE requiere mayoría de dos tercios de los votos emitidos que representen la mayoría de los diputados (art.234 TFUE).'}},
{n:74, q:'Con respecto al Parlamento Europeo, indique la respuesta incorrecta:', o:{a:'Celebra dos periodos de sesiones al año.',b:'Se reúne, sin necesidad de previa convocatoria, el segundo martes del mes de marzo.',c:'Puede reunirse en sesiones extraordinarias a petición de la mayoría de los miembros que lo componen, del Consejo, o de la Comisión.',d:'Sus sesiones son públicas.'}, correct:'a', why:{a:'La opción incorrecta es a: el PE NO celebra solo dos períodos de sesiones al año; celebra sesiones plenarias mensualmente.'}},
{n:75, q:'La Secretaría General del parlamento europeo está en:', o:{a:'Luxemburgo.',b:'Bruselas.',c:'Estrasburgo.',d:'Maastricht.'}, correct:'a', why:{a:'La Secretaría General del PE tiene su sede en Luxemburgo.'}},
{n:76, q:'El Parlamento Europeo, normalmente, adopta sus decisiones:', o:{a:'Por mayoría de los votos emitidos.',b:'Por el sistema de doble mayoría.',c:'Por mayoría de dos tercios.',d:'Por consenso.'}, correct:'a', why:{a:'El art.231 TFUE: el PE se pronuncia por mayoría de los votos emitidos, salvo disposición contraria.'}},
{n:77, q:'De las siguientes instituciones de la Unión Europea, indique aquella que no ejerce actividad legislativa alguna.', o:{a:'La Comisión.',b:'El Parlamento Europeo.',c:'El Consejo Europeo.',d:'Todos los citados en las respuestas anteriores ejercen actividad legislativa.'}, correct:'b', why:{b:'El Consejo Europeo no ejerce función legislativa; define orientaciones políticas generales (art.15 TUE).'}},
{n:78, q:'En el ámbito de la Unión Europea tiene el derecho de proponer nueva legislación:', o:{a:'El Consejo de la Unión Europea.',b:'El Consejo Europeo.',c:'La Comisión Europea.',d:'El Parlamento Europeo.'}, correct:'c', why:{c:'El derecho de iniciativa legislativa en la UE corresponde en exclusiva a la Comisión Europea (art.17.2 TUE).'}},
{n:79, q:'En el ámbito de la Unión Europea, la definición de las orientaciones y prioridades políticas generales y la adopción de los impulsos necesarios para el desarrollo de la Unión corresponde a:', o:{a:'El Parlamento Europeo.',b:'El Consejo Europeo.',c:'El Consejo de la Unión Europea.',d:'La Comisión Europea.'}, correct:'b', why:{b:'El art.15.1 TUE: el Consejo Europeo define las orientaciones y prioridades políticas generales de la UE.'}},
{n:80, q:'¿Qué órgano promueve el interés general de la Unión Europea y vela porque se apliquen los Tratados y las medidas adoptadas por sus Instituciones?', o:{a:'La Comisión Europea.',b:'El Parlamento Europeo.',c:'El Consejo de la Unión Europea.',d:'El Consejo Europeo.'}, correct:'a', why:{a:'La Comisión Europea es guardiana de los Tratados (art.17.1 TUE).'}},
{n:81, q:'Las sesiones del Consejo de la Unión Europea son públicas:', o:{a:'En todo caso.',b:'En ningún caso.',c:'Cuando delibere y vote sobre un proyecto de acto legislativo.',d:'Durante los debates sobre ampliación del número de miembros de la Unión.'}, correct:'d', why:{d:'El art.16.8 TUE: el Consejo se reunirá en público cuando delibere y vote sobre proyectos de acto legislativo.'}},
{n:82, q:'La función legislativa de la Unión Europea es ejercida:', o:{a:'Por el Consejo Europeo.',b:'Por la Comisión Europea y el Consejo Europeo.',c:'Por el Parlamento Europeo exclusivamente.',d:'Conjuntamente por el Parlamento Europeo y el Consejo de la Unión Europea.'}, correct:'b', why:{b:'La función legislativa es ejercida conjuntamente por el PE y el Consejo de la UE (art.289 TFUE).'}},
{n:83, q:'Ejerce funciones de ejecución del Presupuesto y sobre gestión de los programas de la Unión Europea:', o:{a:'El Consejo Europeo.',b:'El Consejo de la Unión Europea.',c:'La Comisión Europea.',d:'El Parlamento Europeo.'}, correct:'d', why:{d:'La Comisión ejecuta el presupuesto y gestiona los programas europeos (art.317 TFUE).'}},
{n:84, q:'Los trabajos del Consejo Europeo son preparados por:', o:{a:'La Comisión Europea.',b:'El Comité de las Regiones.',c:'El Alto representante de la Unión para Asuntos Exteriores y Política de Seguridad.',d:'Un Comité compuesto por Representantes Permanentes de los Gobiernos de los Estados miembros.'}, correct:'d', why:{d:'El COREPER (Comité de Representantes Permanentes) prepara los trabajos del Consejo de la UE.'}},
{n:85, q:'El mandato de la Comisión Europea es de:', o:{a:'5 años.',b:'4 años.',c:'2 años y medio.',d:'8 años.'}, correct:'a', why:{a:'El mandato de la Comisión Europea es de cinco años.'}},
{n:86, q:'El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad de la Unión Europea es nombrado y cesado por:', o:{a:'El Parlamento Europeo con el visto bueno de la Comisión.',b:'El Consejo Europeo con la aprobación del Presidente de la Comisión.',c:'El Consejo con la aprobación del Comité de Representantes Permanentes.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art.18.1 TUE: el Alto Representante es nombrado por el Consejo Europeo con aprobación del Presidente de la Comisión.'}},
{n:87, q:'En el ámbito de la Unión Europea, la llamada "minoría de bloqueo" se puede producir en el seno de:', o:{a:'La Comisión Europea.',b:'El Consejo de la Unión Europea.',c:'El Consejo Europeo.',d:'El Parlamento Europeo.'}, correct:'b', why:{b:'La minoría de bloqueo opera en el Consejo de la UE cuando se vota por mayoría cualificada.'}},
{n:88, q:'En el Consejo de la Unión Europea, la minoría de bloqueo está compuesta por:', o:{a:'4 miembros que representen, al menos, el 55% de la población total de la Unión Europea.',b:'Al menos 4 miembros que representen, como mínimo, el 35 % de la población total de la Unión Europea.',c:'Al menos 4 miembros que representen, como mínimo, el 55% de la población total de la Unión Europea.',d:'4 miembros que representen, al menos, el 65% de la población total de la Unión Europea.'}, correct:'b', why:{b:'La minoría de bloqueo requiere al menos 4 Estados miembros que representen al menos el 35% de la población de la UE (art.16.4 TUE).'}},
{n:89, q:'La sede la Comisión Europea está en:', o:{a:'Luxemburgo.',b:'Bruselas.',c:'Luxemburgo, aunque cuenta con diversos servicios en Bruselas.',d:'Bruselas, aunque cuenta con diversos servicios en Luxemburgo.'}, correct:'d', why:{d:'La Comisión Europea tiene su sede en Bruselas.'}},
{n:90, q:'Las decisiones del Consejo Europeo se adoptan:', o:{a:'Por mayoría simple, salvo que los Tratados dispongan otra cosa.',b:'Por consenso, salvo que los Tratados dispongan otra cosa.',c:'Por unanimidad, salvo que los Tratados dispongan otra cosa.',d:'Por mayoría cualificada, salvo que los Tratados dispongan otra cosa.'}, correct:'b', why:{b:'El art.15.4 TUE: el Consejo Europeo se pronunciará por consenso, salvo disposición contraria.'}},
{n:91, q:'El Alto Representante de la Unión Europea para Asuntos Exteriores y Política de Seguridad:', o:{a:'Es también uno de los vicepresidentes de la Comisión.',b:'Es también el Presidente del Consejo de Asuntos Exteriores de la Unión.',c:'Las respuestas a y b son correctas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El Alto Representante es a la vez Vicepresidente de la Comisión y preside el Consejo de Asuntos Exteriores.'}},
{n:92, q:'En el ámbito de la Unión Europea, defina lo que se entiende por doble mayoría:', o:{a:'En el proceso de toma de decisiones del Parlamento Europeo, la mayoría cualificada se alcanza cuando votan a favor un mínimo del 55 % de los miembros del Parlamento, que representen al menos a 15 estados miembros y el 65 % de la población.',b:'En el proceso de toma de decisiones del Consejo de la Unión Europea, la mayoría cualificada se alcanza cuando votan a favor un mínimo del 55 % de los Estados miembros del Consejo, que incluya al menos a 15 de ellos, y que representen como mínimo el 65 % de la población de la Unión.',c:'En el proceso de toma de decisiones del Parlamento Europeo, la mayoría cualificada se alcanza cuando votan a favor un mínimo del 65 % de los miembros.',d:'En el proceso de toma de decisiones del Consejo, la mayoría cualificada se alcanza cuando votan a favor un mínimo del 65 % de los miembros.'}, correct:'b', why:{b:'La doble mayoría en el Consejo requiere al menos el 55% de Estados miembros (mínimo 15) que representen el 65% de la población (art.16.4 TUE).'}},
{n:93, q:'Cuando el Consejo de la Unión Europea vote propuestas que no emanen de la Comisión, ni del Alto Representante, para adoptar decisiones se exige...', o:{a:'Que al menos el 75% de los miembros del Consejo voten a favor, y que sus países representen al menos el 55% de la población.',b:'Que al menos el 55% de los miembros del Consejo voten a favor, y que representen el 55% de la población.',c:'Que al menos el 72% de los miembros del Consejo voten a favor, y que representen al menos el 65% de la UE.',d:'Que al menos el 72% de los miembros del Consejo voten a favor, y que representen al menos el 55% de la población.'}, correct:'c', why:{c:'Art.238.2 TFUE: sin propuesta de la Comisión, se requiere el 72% de los miembros del Consejo que representen el 65% de la población.'}},
{n:94, q:'Actualmente, la Comisión Europea está compuesta por:', o:{a:'27 Comisarios (uno por cada país miembro).',b:'54 Comisarios (dos por cada país miembro).',c:'Un número correspondiente a la mitad más uno del número de estados miembros.',d:'14 Comisarios elegidos por los estados miembros.'}, correct:'a', why:{a:'La Comisión Europea está compuesta por un Comisario por Estado miembro (27 en total).'}},
{n:95, q:'El Consejo de la Unión Europea está compuesto por:', o:{a:'Un representante de cada estado miembro con rango ministerial.',b:'Los Jefes de Estado o de Gobierno de los Estados miembros.',c:'Un nacional de cada Estado miembro.',d:'Los miembros elegidos por los ciudadanos mediante sufragio.'}, correct:'a', why:{a:'El art.16.2 TUE: el Consejo de la UE está compuesto por un representante de rango ministerial de cada Estado.'}},
{n:96, q:'¿Qué institución de la Unión Europea tiene su sede en Bruselas, aunque en los meses de abril, junio y octubre celebra sus sesiones en Luxemburgo?', o:{a:'El Parlamento Europeo.',b:'La Comisión Europea.',c:'El Consejo Europeo.',d:'El Consejo de la Unión Europea.'}, correct:'d', why:{d:'El Consejo de la UE tiene sede en Bruselas y celebra sesiones en Luxemburgo en abril, junio y octubre.'}},
{n:97, q:'Los miembros de la Comisión Europea y su Presidente deben someterse al voto de aprobación del Parlamento Europeo.', o:{a:'Falso, el voto de aprobación que necesitan es el del Consejo Europeo.',b:'Falso, el voto de aprobación que necesitan lo emite el Consejo.',c:'Las respuestas a y b son correctas.',d:'Cierto, y también debe someterse a este voto el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.'}, correct:'d', why:{d:'El Colegio de Comisarios, incluido el Alto Representante, debe someterse al voto de aprobación del PE (art.17.7 TUE).'}},
{n:98, q:'El poder ejecutivo de la Unión Europea corresponde a...', o:{a:'El Parlamento Europeo.',b:'La Comisión Europea.',c:'El Consejo Europeo.',d:'El Consejo de la Unión Europea.'}, correct:'b', why:{b:'La función ejecutiva en la UE corresponde principalmente a la Comisión Europea.'}},
{n:99, q:'Supervisa el derecho de la Unión Europea, bajo el control del Tribunal de Justicia de la Unión Europea...', o:{a:'El Parlamento Europeo.',b:'La Comisión Europea.',c:'El Consejo Europeo.',d:'El Consejo de la Unión Europea.'}, correct:'b', why:{b:'La Comisión supervisa la aplicación del Derecho de la UE bajo el control del TJUE.'}},
{n:100, q:'Forma parte del Colegio de Comisarios de la Comisión Europea...', o:{a:'El Alto Representante de la Unión.',b:'El Defensor del Pueblo Europeo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Alto Representante forma parte del Colegio de Comisarios como Vicepresidente de la Comisión.'}},
{n:101, q:'En el ámbito de la Unión Europea y con relación a la moción de censura, indique la respuesta correcta:', o:{a:'Se vota ante el Parlamento Europeo.',b:'Si la moción de censura se aprueba, los miembros de la Comisión y el Alto representante deben dimitir.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La moción de censura se vota ante el PE y si se aprueba, la Comisión y el Alto Representante deben dimitir (art.234 TFUE).'}},
{n:102, q:'El Consejo Europeo...', o:{a:'Se reúne cuatro veces al año.',b:'Necesita de mayoría cualificada para elegir al Presidente del Banco Central Europeo.',c:'Elige a su Presidente para un periodo de dos años y medio.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El Consejo Europeo se reúne dos veces por semestre (cuatro veces al año), elige su Presidente para 2,5 años y nombra al Presidente del BCE.'}},
{n:103, q:'La presidencia de la Unión Europea es rotatoria entre los estados miembros, por un periodo de...', o:{a:'Dos años y medio.',b:'Un año.',c:'Seis meses.',d:'Tres meses.'}, correct:'c', why:{c:'La Presidencia rotatoria del Consejo de la UE corresponde a cada Estado miembro por turnos de seis meses.'}},
{n:104, q:'El Consejo de la Unión Europea nombra por mayoría cualificada a los miembros...', o:{a:'Del Comité Económico y Social europeo.',b:'Del Tribunal de Cuentas Europeo.',c:'Del Comité de las Regiones de la Unión Europea.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El Consejo de la UE nombra por mayoría cualificada a los miembros del CESE, del CDR y del Tribunal de Cuentas.'}},
{n:105, q:'El Consejo de la Unión Europea nombra por mayoría cualificada a los miembros...', o:{a:'Del Comité Económico y Social europeo.',b:'Del Tribunal de Cuentas Europeo.',c:'Del Comité de las Regiones de la Unión Europea.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El Consejo de la UE nombra por mayoría cualificada a los miembros del CESE, del CDR y del Tribunal de Cuentas.'}},
{n:106, q:'Forman parte del Colegio de Comisarios de la Unión Europea...', o:{a:'Nueve vicepresidentes.',b:'Dieciocho comisarios.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Colegio de Comisarios está compuesto por 27 Comisarios (uno por Estado miembro), incluyendo el Presidente y varios Vicepresidentes.'}},
{n:107, q:'El Tribunal de Justicia de la Unión Europea:', o:{a:'Está constituido por el Tribunal de Justicia, el Tribunal General y los tribunales especializados.',b:'Tiene su sede en Bruselas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El TJUE comprende el Tribunal de Justicia, el Tribunal General y los tribunales especializados. Tiene sede en Luxemburgo.'}},
{n:108, q:'En el ámbito de la Unión Europea, el Tribunal de Justicia:', o:{a:'Está compuesto por un Juez de cada Estado miembro y es asistido por 12 abogados generales.',b:'Tiene por misión la interpretación y aplicación de los Tratados por los Estados miembros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El TJ de la UE tiene por misión garantizar el respeto del Derecho en la interpretación y aplicación de los Tratados.'}},
{n:109, q:'En el ámbito de la Unión Europea, el Tribunal de Justicia:', o:{a:'Se constituye en Salas de tres y cinco magistrados.',b:'Se constituye en Gran Sala que está compuesta por 15 miembros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El TJ puede reunirse en Pleno, en Gran Sala (15 jueces) o en Salas de 3 o 5 jueces.'}},
{n:110, q:'Con respecto al Presidente del Tribunal de Justicia de la Unión Europea, indique la respuesta incorrecta:', o:{a:'Forma parte de la Gran Sala de Justicia.',b:'Es elegido por los Jueces del Tribunal.',c:'Es elegido para un periodo de 3 años.',d:'Su mandato no es renovable.'}, correct:'d', why:{d:'El mandato del Presidente del TJUE SÍ es renovable; es elegido por 3 años y puede ser reelegido.'}},
{n:111, q:'En el ámbito de la Unión Europea, el Tribunal General está compuesto por:', o:{a:'Dos jueces por cada Estado miembro.',b:'12 jueces más el Presidente del TJUE.',c:'Los Presidentes de las Salas de 5 jueces.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El Tribunal General está compuesto por al menos dos jueces por Estado miembro.'}},
{n:112, q:'Los Jueces del Tribunal de Justicia y del Tribunal General de la Unión Europea son elegidos:', o:{a:'Por un periodo de 5 años, con renovación parcial cada dos años y medio.',b:'Por un periodo de 5 años, sin posibilidad de renovación.',c:'Por un periodo de 6 años, sin posibilidad de renovación.',d:'Por un periodo de 6 años, con renovación parcial cada 3 años.'}, correct:'d', why:{d:'Los jueces del TJ y TG son nombrados para un mandato de 6 años, con renovación parcial cada 3 años.'}},
{n:113, q:'En el ámbito de la Unión Europea ¿Quién crea los tribunales especializados?', o:{a:'Los tribunales especializados no existen.',b:'La Comisión.',c:'El Parlamento Europeo y el Consejo.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art.257 TFUE: el PE y el Consejo pueden crear tribunales especializados adjuntos al Tribunal General.'}},
{n:114, q:'En el ámbito de la Unión Europea, el conocimiento de los recursos contra la Oficina de la Propiedad Intelectual (EUIPO) corresponde a...', o:{a:'El Tribunal de Justicia de la Unión Europea.',b:'El Tribunal General.',c:'El Tribunal especializado en la materia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El Tribunal General es competente para conocer de los recursos contra las resoluciones de la EUIPO.'}},
{n:115, q:'En el ámbito de la Unión Europea, el conocimiento de los litigios entre las instituciones de la Unión Europea y su personal se atribuye a...', o:{a:'El Tribunal de Justicia de la Unión Europea.',b:'El Tribunal General.',c:'El Tribunal especializado en la materia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El Tribunal General es competente para los litigios entre las instituciones y su personal.'}},
{n:116, q:'En el ámbito de la Unión Europea, el conocimiento de los recursos de anulación, contra un acto de una institución u órgano de la Unión Europea, corresponde a...', o:{a:'El Tribunal de Justicia de la Unión Europea.',b:'El Tribunal General.',c:'El Tribunal especializado en la materia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Los recursos de anulación se interponen ante el TG en primera instancia, con posible recurso de casación ante el TJ.'}},
{n:117, q:'En el ámbito de la Unión Europea, el conocimiento de los recursos de cualquier estado miembro contra la Comisión, corresponde a...', o:{a:'El Tribunal de Justicia de la Unión Europea.',b:'El Tribunal General.',c:'El Tribunal especializado en la materia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El TJ de la UE conoce en exclusiva de los recursos de los Estados miembros contra la Comisión.'}},
{n:118, q:'En el ámbito de la Unión Europea, el conocimiento de los recursos de omisión contra la inactividad de las instituciones, corresponde a...', o:{a:'El Tribunal de Justicia de la Unión Europea.',b:'El Tribunal General.',c:'El Tribunal especializado en la materia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Los recursos de omisión se interponen ante el TJ o el TG, según el demandante.'}},
{n:119, q:'En el ámbito de la Unión Europea, el conocimiento de los recursos para obtener reparación de daños causados por las instituciones de la UE, corresponde a...', o:{a:'El Tribunal de Justicia de la Unión Europea.',b:'El Tribunal General.',c:'El Tribunal especializado en la materia.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Las acciones de responsabilidad por daños causados por las instituciones de la UE se interponen ante el Tribunal General.'}},
{n:120, q:'El Sistema Europeo de Bancos Centrales (SEBC) está formado por:', o:{a:'El Banco Central Europeo y el Tribunal de Cuentas Europeo.',b:'El Banco Central Europeo y el Banco Europeo de Inversiones.',c:'El Banco Central Europeo y los bancos centrales nacionales de los Estados miembros.',d:'El BCE y los bancos centrales nacionales solo de los Estados de la Eurozona.'}, correct:'c', why:{c:'El SEBC está formado por el BCE y los bancos centrales nacionales de TODOS los Estados miembros (no solo los de la Eurozona).'}},
{n:121, q:'El Sistema Europeo de Bancos Centrales (SBEC):', o:{a:'Está dirigido por los órganos rectores del Banco Central Europeo.',b:'Tiene como objetivo principal mantener la estabilidad de precios y apoyar las políticas económicas.',c:'Las respuestas a y b son correctas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El SEBC está dirigido por los órganos rectores del BCE y tiene como objetivo mantener la estabilidad de precios.'}},
{n:122, q:'Con respecto al Consejo de Gobierno del Banco Central Europeo, indique la respuesta incorrecta:', o:{a:'Define la política monetaria y fija los tipos de interés.',b:'No puede tomar decisiones relativas al marco general en que se adoptan las decisiones de supervisión.',c:'Está formado por el Comité ejecutivo y los representantes de los 19 Bancos Centrales de los países de la Eurozona.',d:'Aprueba los proyectos de decisiones completos propuestos por el Consejo de Supervisión mediante el procedimiento de no objeción.'}, correct:'b', why:{b:'La opción incorrecta es la b: el Consejo de Gobierno SÍ puede tomar decisiones sobre el marco general de las decisiones de supervisión.'}},
{n:123, q:'El Banco Central Europeo...', o:{a:'Es el organismo encargado de gestionar el euro y proteger la estabilidad de precios en la Unión Europea.',b:'Tiene su sede en Luxemburgo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El BCE gestiona el euro y protege la estabilidad de precios. Tiene sede en Fráncfort, no en Luxemburgo.'}},
{n:124, q:'El Banco Central Europeo:', o:{a:'Fue creado por el Tratado de Amsterdam.',b:'Su objetivo principal es mantener la estabilidad de precios y el apoyo a la Unión en el desarrollo de sus políticas económicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El BCE fue creado por el TUE/Maastricht. El Tratado de Ámsterdam reforzó su estatuto. Su objetivo principal es la estabilidad de precios.'}},
{n:125, q:'El Presidente del Banco Central Europeo:', o:{a:'Es elegido por el Consejo.',b:'Es elegido para un periodo de 5 años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El Presidente del BCE es nombrado por el Consejo Europeo para un mandato de 8 años no renovable.'}},
{n:126, q:'El Consejo General del Banco Central Europeo:', o:{a:'Ejerce funciones consultivas y de coordinación.',b:'Está formado por el Presidente y Vicepresidente del BCE, y los gobernadores de los bancos centrales de los 19 países de la Eurozona.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El Consejo General del BCE ejerce funciones consultivas y de coordinación, integrado por el Presidente, Vicepresidente y gobernadores de TODOS los bancos centrales nacionales.'}},
{n:127, q:'El Comité Ejecutivo del Banco Central Europeo:', o:{a:'Está compuesto por el Presidente, el Vicepresidente y otros cuatro miembros.',b:'Las personas que lo componen son nombradas por los países de la Eurozona, por un periodo de 8 años.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Comité Ejecutivo del BCE tiene 6 miembros (Presidente, Vicepresidente y 4 más) nombrados para 8 años no renovables.'}},
{n:128, q:'El Banco Central Europeo y los bancos centrales de los estados miembros cuya moneda es el euro constituyen...', o:{a:'El Sistema Europeo de Bancos Centrales (SEBC).',b:'El Eurosistema.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Eurosistema es el formado por el BCE y los bancos centrales nacionales de los países con el euro. El SEBC incluye todos los bancos centrales de la UE.'}},
{n:129, q:'Con relación a las Instituciones de la Unión Europea, indique la respuesta incorrecta:', o:{a:'El Banco Central Europeo y los bancos centrales nacionales de los Estados miembros cuya moneda es el Euro constituyen el SEBC.',b:'El Presidente del Tribunal de Justicia de la Unión Europea es elegido por un periodo de 3 años, con posibilidad de renovación.',c:'Los miembros del Comité Económico y Social no están vinculados por mandato imperativo.',d:'La Comisión podrá asistir a todas las sesiones del Parlamento Europeo.'}, correct:'a', why:{a:'La opción incorrecta es la a: el SEBC está formado por el BCE y los bancos centrales de TODOS los Estados miembros (no solo los de la Eurozona). El Eurosistema es el que incluye solo los de la Eurozona.'}},
{n:130, q:'La sede del Banco Central Europeo está en:', o:{a:'Estrasburgo.',b:'Bruselas.',c:'Fráncfort.',d:'Luxemburgo.'}, correct:'c', why:{c:'La sede del Banco Central Europeo está en Fráncfort del Meno (Alemania).'}},
{n:131, q:'Los órganos de gobierno del Banco Central Europeo son:', o:{a:'El Comité Superior, el Comité Ejecutivo, y el Consejo Económico.',b:'El Comité Ejecutivo, el Consejo de Gobierno, y el Consejo General.',c:'El Comité Superior, el Comité Ejecutivo, y el Consejo General.',d:'El Comité Ejecutivo, El Consejo Económico y el Consejo General.'}, correct:'b', why:{b:'Los órganos de gobierno del BCE son: el Consejo de Gobierno, el Comité Ejecutivo y el Consejo General.'}},
{n:132, q:'El órgano de gobierno del Banco Central Europeo que ejerce funciones consultivas y de coordinación se denomina:', o:{a:'Consejo General.',b:'Consejo Económico.',c:'Comité Ejecutivo.',d:'Consejo de Gobierno.'}, correct:'a', why:{a:'El Consejo General del BCE ejerce funciones consultivas y de coordinación.'}},
{n:133, q:'Define la política monetaria y fija los tipos de interés en el ámbito de la Unión Europea.', o:{a:'El Comité Ejecutivo del Banco Central Europeo.',b:'El Consejo General del Banco Central Europeo.',c:'El Consejo de Gobierno del Banco Central Europeo.',d:'El Comité Económico del Banco Central Europeo.'}, correct:'d', why:{d:'El Consejo de Gobierno del BCE es el órgano supremo responsable de definir la política monetaria y fijar los tipos de interés.'}},
{n:134, q:'Con respecto al Tribunal de Cuentas Europeo, indique la respuesta correcta:', o:{a:'Se encarga de la fiscalización y control de las cuentas de la Unión.',b:'Tiene su sede en Bruselas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El Tribunal de Cuentas Europeo fiscaliza las cuentas de la UE. Tiene sede en Luxemburgo, no en Bruselas.'}},
{n:135, q:'El Tribunal de Cuentas Europeo está compuesto por:', o:{a:'Veinte Jueces elegidos por la Comisión.',b:'Un nacional de cada Estado miembro.',c:'Veinte jueces cualificados elegidos por el Parlamento Europeo.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El Tribunal de Cuentas Europeo está compuesto por un nacional de cada Estado miembro (27 en total).'}},
{n:136, q:'Los miembros del Tribunal de Cuentas Europeo tienen una duración en el cargo de:', o:{a:'5 años.',b:'4 años.',c:'6 años.',d:'8 años.'}, correct:'d', why:{d:'Los miembros del Tribunal de Cuentas Europeo tienen un mandato de 6 años, renovable.'}},
{n:137, q:'El Presidente del Tribunal de Cuentas Europeo:', o:{a:'Es elegido por los miembros del propio Tribunal por un periodo de tres años.',b:'Puede ser renovado en el cargo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Presidente del TCE es elegido por los miembros del Tribunal para un mandato de 3 años, renovable.'}},
{n:138, q:'Los órganos consultivos de la Unión Europea son:', o:{a:'El Alto Representante y el Defensor del Pueblo.',b:'El COREPER y el Tribunal de Cuentas Europeo.',c:'El Comité Económico y Social (CESE) y el Comité de las Regiones (CDR).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Los órganos consultivos de la UE son el CESE y el CDR. Las opciones a y b son incorrectas.'}},
{n:139, q:'Los órganos consultivos de la Unión Europea asisten:', o:{a:'Al Consejo, al Banco Central Europeo y a la Comisión.',b:'Al Parlamento, al Consejo y a la Comisión.',c:'Al Parlamento, a la Comisión y al Comité de las Regiones.',d:'A todas las instituciones de la Unión Europea.'}, correct:'b', why:{b:'Los órganos consultivos (CESE y CDR) asisten al Parlamento Europeo, al Consejo y a la Comisión Europea.'}},
{n:140, q:'El órgano de la Unión Europea en el que están presentes representantes de las organizaciones de empresarios y trabajadores recibe el nombre de:', o:{a:'Comité de las Regiones.',b:'Comité Económico y Social.',c:'Confederación de Sindicatos y Empresarios de la Unión Europea.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El Comité Económico y Social (CESE) incluye representantes de empresarios, trabajadores y sociedad civil organizada.'}},
{n:141, q:'En el ámbito de la Unión Europea, el número de miembros del Comité de las Regiones, en la actualidad, es de:', o:{a:'352.',b:'329.',c:'350.',d:'253.'}, correct:'b', why:{b:'El Comité de las Regiones de la UE tiene 329 miembros actualmente.'}},
{n:142, q:'Un concejal de cualquier Ayuntamiento de España puede estar presente en la Unión Europea formando parte de:', o:{a:'El Comité Económico y Social.',b:'El Comité de las Regiones.',c:'El Consejo.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El Comité de las Regiones incluye representantes de los entes regionales y locales, incluidos los concejales.'}},
{n:143, q:'En el ámbito de la Unión Europea ¿cuál de las siguientes instituciones está formada actualmente por 329 miembros?', o:{a:'El Comité Económico y Social.',b:'El Comité de las Regiones.',c:'El COREPER.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'El CESE y el CDR tienen ambos 329 miembros. Las respuestas a y b serían correctas.'}},
{n:144, q:'El Presidente del Comité Económico y Social de la Unión Europea es elegido por los miembros de ésta institución para un periodo de:', o:{a:'5 años.',b:'4 años.',c:'3 años.',d:'2 años y medio.'}, correct:'d', why:{d:'El Presidente del CESE es elegido para un mandato de dos años y medio.'}},
{n:145, q:'La Mesa del Comité de las Regiones es designada:', o:{a:'Por los propios miembros de dicho Comité.',b:'Por un periodo de 5 años.',c:'Lo reflejado en las respuestas a y b es correcto.',d:'Ninguna de las respuestas anteriores es correcto.'}, correct:'a', why:{a:'La Mesa del Comité de las Regiones es elegida por los propios miembros del Comité.'}},
{n:146, q:'El Banco Europeo de Inversiones (BEI)...', o:{a:'Contribuye al desarrollo equilibrado y estable del mercado interior de la UE.',b:'No tiene finalidad lucrativa.',c:'Financia proyectos para el desarrollo de las regiones más atrasadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El BEI: contribuye al desarrollo equilibrado de la UE, no tiene fin lucrativo y financia proyectos en regiones menos desarrolladas.'}},
{n:147, q:'Los Estatutos del Banco Europeo de Inversiones pueden ser modificados por:', o:{a:'La Comisión, previa consulta al propio Banco y al Consejo.',b:'El Consejo, previa consulta al propio Banco y a la Comisión.',c:'El Consejo, previa consulta al Parlamento Europeo y al propio Banco.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Los Estatutos del BEI pueden ser modificados por el Consejo, previa consulta al PE y al propio Banco.'}},
{n:148, q:'Concede préstamos y garantías a los Estados de la Unión Europea, sin ánimo de lucro:', o:{a:'El Banco Central Europeo.',b:'El SEBC.',c:'El Banco Europeo de Inversiones.',d:'El Tribunal de Cuentas Europeo.'}, correct:'c', why:{c:'El BEI concede préstamos y garantías sin ánimo de lucro para financiar proyectos de inversión en la UE.'}},
{n:149, q:'En el ámbito de la Unión Europea, no es renovable el mandato de:', o:{a:'El Presidente del Tribunal de Cuentas Europeo.',b:'Los miembros del Consejo de Gobierno del Banco Central Europeo.',c:'El Presidente del Tribunal de Justicia de la Unión Europea.',d:'El Defensor del Pueblo Europeo.'}, correct:'b', why:{b:'Los miembros del Comité Ejecutivo del BCE tienen mandato de 8 años NO renovable. El Presidente del TCE, del TJUE y el Defensor del Pueblo SÍ pueden ser renovados.'}},
{n:150, q:'Con respecto al Banco Europeo de Inversiones de la Unión Europea, indique la respuesta incorrecta:', o:{a:'Su Consejo de Administración consta de un miembro designado por cada país de la Unión, y otro por la Comisión Europea.',b:'Todos los estados de la UE son miembros del Banco Europeo de Inversiones.',c:'En el Consejo de Gobernadores solo participan los ministros de economía de los países de la Eurozona.',d:'El Comité de Dirección es el órgano ejecutivo del Banco que gestiona los asuntos corrientes.'}, correct:'c', why:{c:'La opción incorrecta es la c: el Consejo de Gobernadores del BEI incluye Ministros de TODOS los Estados miembros, no solo los de la Eurozona.'}},
{n:151, q:'El Servicio Europeo de Acción Exterior (SEAE).', o:{a:'Es el cuerpo diplomático de la Unión Europea.',b:'Depende directamente del Comité de las Regiones.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El SEAE actúa como cuerpo diplomático de la UE bajo la autoridad del Alto Representante, no del Comité de las Regiones.'}},
{n:152, q:'El Servicio Europeo de Acción Exterior (SEAE).', o:{a:'Está constituido por 27 representantes (uno de cada estado miembro).',b:'Está dirigido por el Alto Representante para Asuntos Exteriores y Política de Seguridad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El SEAE trabaja bajo la autoridad del Alto Representante de la UE para Asuntos Exteriores.'}},
{n:153, q:'El Supervisor Europeo de Protección de Datos (SEPD)...', o:{a:'Es designado por la Comisión.',b:'Es nombrado por el Parlamento Europeo y el Consejo de la Unión Europea.',c:'Tiene un mandato de 5 años renovables.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El SEPD es nombrado por el PE y el Consejo para un mandato de 5 años renovable, siendo correctas b y c.'}},
{n:154, q:'La sede del Supervisor Europeo de Protección de Datos está en...', o:{a:'Fráncfort.',b:'Bruselas.',c:'Luxemburgo.',d:'Estrasburgo.'}, correct:'b', why:{b:'La sede del SEPD está en Bruselas.'}},
{n:155, q:'La adhesión a las Comunidades Europeas y la recepción del Derecho Comunitario en España:', o:{a:'Cambió el sistema de fuentes de Derecho existente hasta el momento.',b:'Al principio de jerarquía, añadió el principio de competencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La adhesión de España a la CE transformó el sistema de fuentes del Derecho, añadiendo el principio de competencia al de jerarquía.'}},
{n:156, q:'A los efectos de las fuentes del ordenamiento jurídico español, el Derecho Comunitario:', o:{a:'Es la primera fuente, después de la Constitución.',b:'Es la segunda fuente, después de la Constitución.',c:'Es la tercera fuente, después de la Constitución.',d:'Es un Derecho autónomo, que no depende del derecho de los Estados miembros.'}, correct:'d', why:{d:'El Derecho de la UE es un ordenamiento jurídico autónomo, distinto del derecho internacional y del derecho interno de los Estados miembros.'}},
{n:157, q:'Las fuentes del Derecho Comunitario están constituidas:', o:{a:'Por los Tratados Constitutivos.',b:'Por el Derecho Derivado.',c:'Por los Acuerdos Internacionales suscritos por la Comunidad y los Estados entre sí.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Las fuentes del Derecho de la UE comprenden el Derecho originario (Tratados), el Derecho derivado y los acuerdos internacionales.'}},
{n:158, q:'Los principios generales del Derecho:', o:{a:'Son fuente de Derecho Comunitario.',b:'No son fuente de Derecho Comunitario.',c:'Son fuente de Derecho Comunitario en aquellos países que los tengan reconocidos.',d:'Son fuente solo para los países fundadores de la CEE.'}, correct:'a', why:{a:'Los principios generales del Derecho son reconocidos por el TJUE como fuente del Derecho de la UE.'}},
{n:159, q:'Los Reglamentos Comunitarios:', o:{a:'Tienen alcance general.',b:'Son obligatorios en todos sus elementos.',c:'Son directamente aplicables en todos los Estados miembros.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Los Reglamentos (art.288 TFUE) tienen alcance general, son obligatorios en todos sus elementos y directamente aplicables en todos los EEMM.'}},
{n:160, q:'Las Directivas del Derecho Comunitario:', o:{a:'No son obligatorias.',b:'Obligan a los Estados miembros destinatarios, en cuanto al resultado que debe conseguirse.',c:'Obligan a los Estados miembros destinatarios, a emplear determinadas formas o medios.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'Las Directivas (art.288 TFUE) obligan al Estado destinatario en cuanto al resultado, dejando libertad sobre la forma y medios de transposición.'}},
{n:161, q:'Las normas emanadas de la Unión Europea que obligan a los Estados miembros en cuanto al resultado pero dejan libertad sobre la forma y los medios, se denominan:', o:{a:'Reglamentos.',b:'Directivas.',c:'Decisiones.',d:'Recomendaciones.'}, correct:'b', why:{b:'Las Directivas son las normas de la UE que vinculan al EEMM en cuanto al resultado, dejando libertad de transposición.'}},
{n:162, q:'Las Decisiones del Derecho Comunitario:', o:{a:'Obligan directamente a los Estados miembros.',b:'No son obligatorias para los Estados miembros.',c:'Obligan en todos sus elementos a los destinatarios que designan.',d:'Obligan a los EEMM en cuanto al resultado, con libertad de forma y medios.'}, correct:'c', why:{c:'Las Decisiones (art.288 TFUE) son obligatorias en todos sus elementos para sus destinatarios.'}},
{n:163, q:'Las recomendaciones y dictámenes de la Unión Europea:', o:{a:'Obligan directamente a los Estados miembros.',b:'No son obligatorios para los Estados miembros.',c:'Tienen alcance general y son obligatorios en todos sus elementos.',d:'Obligan a los Estados al empleo de determinadas formas y medios.'}, correct:'b', why:{b:'Las Recomendaciones y Dictámenes (art.288 TFUE) no son vinculantes.'}},
{n:164, q:'A la figura jurídica por la que se dice que los destinatarios de las normas europeas son tanto los Estados como los ciudadanos, pudiendo éstos exigir su observancia ante los tribunales, se la conoce con el nombre de:', o:{a:'Primacía.',b:'Efecto directo.',c:'Efecto vertical.',d:'Efecto horizontal.'}, correct:'b', why:{b:'El efecto directo permite a los ciudadanos invocar normas de la UE directamente ante los tribunales nacionales.'}},
{n:165, q:'En el ámbito de la Unión Europea el efecto directo permite...', o:{a:'Que cualquier particular pueda exigir a los jueces de su propio país la eliminación del Derecho Nacional contrario al Derecho comunitario aplicable.',b:'Que cualquier autoridad de la UE pueda modificar el derecho aplicable en cualquiera de los EEMM contrario al Derecho de la Unión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El efecto directo permite a los particulares invocar el Derecho de la UE ante los jueces nacionales para exigir la inaplicación del derecho nacional contrario.'}},
{n:166, q:'El efecto directo que tienen algunas disposiciones de la Unión Europea:', o:{a:'Produce efectos verticales.',b:'Produce efectos horizontales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El efecto directo puede ser vertical (ciudadano vs Estado) y horizontal (entre particulares). No toda norma produce ambos efectos.'}},
{n:167, q:'Cuando decimos que las normas de la Unión Europea pueden invocarse por el particular frente al Estado miembro, nos estamos refiriendo:', o:{a:'A la primacía.',b:'Al efecto directo vertical.',c:'Al efecto directo horizontal.',d:'Al efecto de recepción obligatoria.'}, correct:'b', why:{b:'El efecto directo vertical permite a los particulares invocar normas de la UE frente al Estado miembro.'}},
{n:168, q:'Cuando nos referimos al poder de los particulares para invocar la aplicación de las normas de la Unión Europea, estamos hablando de:', o:{a:'Primacía.',b:'Efecto directo vertical.',c:'Efecto directo horizontal.',d:'Efecto obligatorio.'}, correct:'c', why:{c:'El efecto directo (en general) es el poder de invocar normas de la UE ante los tribunales. El vertical es frente al Estado.'}},
{n:169, q:'Según el Tribunal de Justicia de las Comunidades Europeas, toda disposición legislativa de un Estado que sea contraria a las normas Comunitarias:', o:{a:'Debe ser modificada en el plazo de 3 meses.',b:'Constituye infracción a los Tratados constitutivos de la Unión Europea.',c:'Es inaplicable.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'Conforme a la jurisprudencia del TJUE, la norma nacional contraria al Derecho de la UE es inaplicable.'}},
{n:170, q:'Cuando el Juez de cualquier Estado miembro de la Unión Europea constate la existencia de una norma nacional que contradiga a una norma de la Unión Europea, deberá:', o:{a:'Aplicar la normativa Comunitaria.',b:'Aplicar la normativa de ese Estado.',c:'Elevar al Tribunal de Justicia de la Unión Europea.',d:'Abstenerse de juzgar.'}, correct:'a', why:{a:'El juez nacional debe inaplicar la norma nacional y aplicar la comunitaria, conforme al principio de primacía.'}},
{n:171, q:'El efecto directo de las normas de la Unión Europea:', o:{a:'Alcanza a todo el Derecho Comunitario.',b:'Alcanza a todo el Derecho Comunitario, excepto a los Reglamentos.',c:'Se da respecto de las disposiciones de los Tratados que contienen una obligación clara, precisa e incondicional de hacer o abstenerse.',d:'Solo se da cuando el Estado no ha dictado Derecho interno de desarrollo.'}, correct:'c', why:{c:'El efecto directo requiere que la disposición sea clara, precisa e incondicional, sin necesitar medidas adicionales de ejecución.'}},
{n:172, q:'El efecto directo de las normas de la Unión Europea:', o:{a:'Alcanza, tanto al Derecho originario como al derivado.',b:'Alcanza a los Tratados, Reglamentos, Directivas y decisiones.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El efecto directo puede alcanzar tanto al Derecho originario como al derivado, dependiendo del tipo de norma y si cumple los requisitos.'}},
{n:173, q:'La "primacía" del Derecho Unión Europea...', o:{a:'Consiste en la imposibilidad que tienen los Estados de hacer prevalecer, contra las normas europeas, una medida unilateral ulterior.',b:'Es el hecho de que los destinatarios de las normas Europeas son, tanto los Estados miembros como los particulares.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La primacía impide a los Estados hacer prevalecer medidas nacionales sobre el Derecho de la UE.'}},
{n:174, q:'La "primacía" del Derecho de la Unión Europea se da con carácter incondicional y absoluto, aplicándose esta regla incluso a las normas Constitucionales:', o:{a:'Cierto.',b:'Falso; la Constitución siempre prevalece sobre cualquier otro Derecho.',c:'Falso; la primacía se da únicamente respecto a normas con rango inferior a ley.',d:'Cierto, pero esta primacía solo la tienen los Tratados; nunca el derecho derivado.'}, correct:'a', why:{a:'Según la jurisprudencia del TJUE, la primacía del Derecho de la UE se aplica incluso frente a las constituciones nacionales.'}},
{n:175, q:'La "primacía" del Derecho de la Unión Europea:', o:{a:'Afecta, tanto al Derecho originario como al derivado.',b:'Afecta solo al Derecho originario.',c:'Afecta solo al Derecho derivado.',d:'No afecta ni al derecho originario ni al derivado.'}, correct:'a', why:{a:'La primacía del Derecho de la UE afecta tanto al Derecho originario como al derivado.'}},
{n:176, q:'Por efecto de la "primacía", las normas internas de un Estado que se oponen a las de la Unión Europea, quedan en una situación de:', o:{a:'Suspensión temporal.',b:'Coexistencia.',c:'Aplicabilidad condicionada.',d:'Inaplicabilidad.'}, correct:'d', why:{d:'Por efecto de la primacía, las normas nacionales contrarias al Derecho de la UE quedan en situación de inaplicabilidad.'}},
{n:177, q:'La función administrativa de velar por la aplicación efectiva del Derecho Comunitario corresponde a:', o:{a:'El Parlamento Europeo.',b:'La Comisión Europea.',c:'El Tribunal de Justicia Europeo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La Comisión Europea vela por la aplicación del Derecho de la UE como guardiana de los Tratados.'}},
{n:178, q:'La función de interpretación y aplicación del Derecho Comunitario corresponde a:', o:{a:'El Parlamento Europeo.',b:'La Comisión Europea.',c:'El Tribunal de Justicia Europeo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El TJUE tiene encomendada la interpretación y aplicación del Derecho de la UE (art.19 TUE).'}},
{n:179, q:'El control, a nivel global sobre la aplicación de las distintas políticas Comunitarias, lo realiza:', o:{a:'El Parlamento Europeo.',b:'La Comisión Europea.',c:'El Tribunal de Justicia de la Unión Europea.',d:'Todos los citados en las respuestas anteriores.'}, correct:'a', why:{a:'El Parlamento Europeo ejerce el control político global de la acción de la UE.'}},
{n:180, q:'El control de la aplicación del Derecho de la Unión Europea corresponde, en cada país:', o:{a:'Al Tribunal Constitucional.',b:'A los Tribunales de ese Estado.',c:'A las Administraciones de ese Estado.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'El control del Derecho de la UE en cada Estado corresponde a los tribunales nacionales y a las administraciones nacionales.'}},
{n:181, q:'Todas las propuestas legislativas de la Unión Europea deben remitirse a los parlamentos nacionales de los estados miembros para que éstos...', o:{a:'En el caso de que la UE deba abstenerse de intervenir se lo comuniquen en el plazo de cuatro semanas.',b:'En el caso de que consideren que se ha infringido el ordenamiento jurídico de la Unión, lo denuncien ante el TJUE en el plazo de ocho semanas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Los parlamentos nacionales tienen 8 semanas para emitir dictamen motivado de subsidiariedad sobre propuestas legislativas de la UE.'}},
{n:182, q:'En el supuesto de que se produzca el incumplimiento del Derecho de la Unión Europea por los particulares de un determinado país:', o:{a:'Las Instituciones Comunitarias son las encargadas de sancionar en todo caso.',b:'Las Instituciones Comunitarias confían a los Estados miembros la función de completar con normas sancionadoras los Reglamentos Comunitarios.',c:'Cada Estado es libre para decidir si sanciona o no al particular infractor.',d:'Las Instituciones Comunitarias sancionan al Estado miembro.'}, correct:'b', why:{b:'Las instituciones de la UE confían a los Estados miembros la función de establecer sanciones nacionales para garantizar el cumplimiento del Derecho de la UE.'}},
{n:183, q:'Cuando un Reglamento de la Unión Europea no contiene sanciones:', o:{a:'Los Estados miembros no lo aplican.',b:'Los Estados miembros no sancionan.',c:'Los Estados miembros no están obligados a controlar la efectiva aplicación de la norma.',d:'Los Estados miembros están obligados a establecerlas.'}, correct:'d', why:{d:'Cuando el Reglamento no prevé sanciones, los Estados deben establecer las medidas sancionadoras necesarias.'}},
{n:184, q:'Cuando un Reglamento de la Unión Europea no contenga sanciones para los supuestos de incumplimiento:', o:{a:'Los Estados miembros tienen discrecionalidad para fijar la naturaleza y cuantía de éstas.',b:'Los Estados deben atenerse a las sanciones establecidas con carácter general por la UE.',c:'Los Estados elaborarán una propuesta de sanción ante la Comisión Europea.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Los Estados tienen discrecionalidad para establecer las sanciones, que deben ser efectivas, proporcionales y disuasorias.'}},
{n:185, q:'En caso de incumplimiento de la normativa de la Unión Europea por parte de los Estados miembros:', o:{a:'La Comisión procede al envío sistemático de comunicaciones para comprobar el cumplimiento de la Directiva.',b:'La Comisión puede plantear recurso ante el TJUE.',c:'Los jueces nacionales pueden dejar de aplicar normas internas en aquello que se oponga a las Directivas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'En caso de incumplimiento: la Comisión puede abrir procedimiento de infracción, el TJUE puede declarar el incumplimiento, y los jueces nacionales pueden inaplicar la norma contraria.'}},
{n:186, q:'El desarrollo de la legislación de la Unión Europea:', o:{a:'Corresponde siempre al Gobierno de la nación.',b:'Corresponde siempre a las Cortes Generales.',c:'Corresponde siempre a las Comunidades Autónomas.',d:'Corresponde al Estado o a las Comunidades Autónomas, según las reglas del reparto ordinario.'}, correct:'d', why:{d:'El desarrollo del Derecho de la UE en España corresponde a quien tenga la competencia en la materia, siguiendo las reglas de distribución competencial.'}},
{n:187, q:'El desarrollo de la legislación de la Unión Europea se reparte entre el Estado y las Comunidades Autónomas conforme a:', o:{a:'Criterios materiales.',b:'Criterios formales.',c:'Criterios jerárquicos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El desarrollo del Derecho de la UE se distribuye entre Estado y CCAA siguiendo criterios materiales (quien tiene la competencia en la materia).'}},
{n:188, q:'Los reglamentos, las directivas y las decisiones de la Unión Europea:', o:{a:'Solo pueden contener actos legislativos.',b:'Solo pueden contener actos no legislativos.',c:'Pueden contener actos legislativos o actos no legislativos.',d:'No son obligatorios para los Estados miembros.'}, correct:'c', why:{c:'Los reglamentos, directivas y decisiones pueden contener actos legislativos o no legislativos.'}},
{n:189, q:'No son impugnables ante el Tribunal de Justicia de la Unión Europea:', o:{a:'Las recomendaciones.',b:'Los dictámenes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Las Recomendaciones y Dictámenes no son vinculantes y no son impugnables directamente ante el TJUE.'}},
{n:190, q:'Las normas de la Unión Europea que permiten a las Instituciones expresarse y proponer una línea de conducta sin establecer una obligación jurídica, reciben el nombre de:', o:{a:'Directivas.',b:'Decisiones.',c:'Recomendaciones.',d:'Dictámenes.'}, correct:'c', why:{c:'Las Recomendaciones permiten a las instituciones expresar su postura sin imponer obligaciones jurídicas.'}},
{n:191, q:'Para invitar a la Comisión Europea a que presente una propuesta sobre cuestiones que los ciudadanos de la Unión estimen que requieren un acto jurídico de ésta, se precisa:', o:{a:'La firma de un millón de ciudadanos de la UE, que sean residentes en un número significativo de EEMM.',b:'La firma de un millón de ciudadanos de la UE, que sean nacionales de un número significativo de EEMM.',c:'La firma de quinientos mil ciudadanos de la UE, que sean nacionales de un número significativo de EEMM.',d:'La firma de quinientos mil ciudadanos de la UE, que sean residentes en un número significativo de EEMM.'}, correct:'b', why:{b:'La Iniciativa Ciudadana Europea requiere 1 millón de ciudadanos de la UE nacionales de al menos 7 Estados miembros.'}},
{n:192, q:'Las normas emanadas de las Instituciones de la Unión Europea que establecen el punto de vista de una institución sobre una determinada cuestión, reciben el nombre de:', o:{a:'Reglamentos.',b:'Recomendaciones.',c:'Dictámenes.',d:'Decisiones.'}, correct:'c', why:{c:'Los Dictámenes expresan el punto de vista de una institución sobre una cuestión determinada.'}},
{n:193, q:'De conformidad con lo establecido en el art.288 del Tratado de Funcionamiento de la Unión Europea, indique cuál de las siguientes afirmaciones no es correcta:', o:{a:'Los Reglamentos tendrán alcance general.',b:'Los Reglamentos serán obligatorios en todos sus elementos y directamente aplicables en cada Estado miembro.',c:'Las Directivas serán obligatorias en todos sus elementos. Cuando designen destinatarios, sólo será obligatoria para éstos.',d:'Las Recomendaciones y los Dictámenes no serán vinculantes.'}, correct:'c', why:{c:'La afirmación incorrecta es c: describe las DECISIONES, no las Directivas. Las Directivas obligan en cuanto al resultado, dejando libertad de forma y medios.'}},
{n:194, q:'El art.288 del Tratado de Funcionamiento de la Unión Europea describe los instrumentos jurídicos de que disponen las instituciones europeas para ejercer sus competencias, siendo estos:', o:{a:'Reglamentos, Órdenes, Directivas y Recomendaciones.',b:'Reglamentos, Órdenes, Directivas, Dictámenes y Recomendaciones.',c:'Reglamentos, Órdenes, Directivas, Instrucciones y Recomendaciones.',d:'Reglamentos, Directivas, Decisiones, Dictámenes y Recomendaciones.'}, correct:'d', why:{d:'El art.288 TFUE establece que los instrumentos jurídicos son: Reglamentos, Directivas, Decisiones, Recomendaciones y Dictámenes.'}},
{n:195, q:'Los parlamentos nacionales de los Estados miembros de la Unión Europea:', o:{a:'Ejercen control sobre los actos jurídicos de la Unión.',b:'Reciben todas las propuestas legislativas de la Unión Europea.',c:'Disponen de 8 semanas para manifestar si consideran que la Unión Europea debe abstenerse de intervenir en un determinado proyecto.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Los parlamentos nacionales reciben las propuestas legislativas de la UE, disponen de 8 semanas para emitir dictamen motivado de subsidiariedad y ejercen control político sobre la acción de la UE.'}},
{n:196, q:'El/los responsable/s ante la Unión Europea de los incumplimientos del Derecho de la misma, es/son:', o:{a:'Siempre el Estado miembro.',b:'El Estado miembro, o las regiones cuando existe una estructura descentralizada.',c:'Las regiones o comunidades autónomas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Ante la UE, el responsable del incumplimiento del Derecho europeo siempre es el Estado miembro, con independencia de si el incumplimiento es imputable al Gobierno central, a una CCAA o a una entidad local.'}},
{n:197, q:'En España, la norma que regula la responsabilidad de las administraciones o entidades descentralizadas por omisión o incumplimiento del Derecho de la Unión Europea es...', o:{a:'La Ley 47/2009.',b:'El RD. 515/2013.',c:'La Ley 49/2007.',d:'El RD. 525/2013.'}, correct:'b', why:{b:'El RD 515/2013 regula los criterios y el procedimiento para determinar y repercutir las responsabilidades por incumplimiento del Derecho de la UE a las Administraciones Públicas y entidades de derecho público descentralizadas.'}},
{n:198, q:'De conformidad con lo dispuesto en el RD. 515/2013, se entenderá que existe incumplimiento del Derecho de la Unión Europea cuando:', o:{a:'Se realicen transposiciones tardías o incorrectas de las Directivas Europeas.',b:'Se mantengan en vigor normas contrarias al Derecho de la Unión Europea.',c:'No se ejecuten sentencias, actos o decisiones dictados por las instituciones europeas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El RD 515/2013 considera incumplimiento del Derecho de la UE: la transposición tardía o incorrecta de directivas, el mantenimiento de normas contrarias al Derecho comunitario, y la no ejecución de sentencias y actos europeos.'}},
{n:199, q:'La Fiscalía Europea...', o:{a:'Se crea mediante el Reglamento UE 2017/1939 del Consejo.',b:'Se estructura en un nivel central y un nivel descentralizado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Fiscalía Europea (EPPO) fue creada por el Reglamento (UE) 2017/1939 del Consejo y se estructura en un nivel central (sede en Luxemburgo) y un nivel descentralizado (Fiscales Europeos delegados en los Estados miembros participantes).'}},
{n:200, q:'La Fiscalía Europea tiene como funciones...', o:{a:'Denunciar las violaciones de derechos humanos, especialmente las referidas a la trata de personas, en cualquiera de los países miembros de la Unión Europea.',b:'Investigar, procesar y llevar a juicio a los autores de delitos contra los intereses financieros de la Unión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La Fiscalía Europea tiene competencia para investigar, procesar y llevar a juicio a los autores de delitos que afecten a los intereses financieros de la UE (fraude, corrupción, blanqueo de capitales, etc.).'}},
{n:201, q:'La aplicación en el Estado Español del Reglamento UE 2017/1939 del Consejo que regula la Fiscalía Europea, se ha llevado a cabo por medio de...', o:{a:'La Ley orgánica 11/2021.',b:'El Real Decreto Legislativo 11/2021.',c:'El Real Decreto Legislativo 9/2021.',d:'La Ley Orgánica 9/2021.'}, correct:'d', why:{d:'La LO 9/2021, de 25 de mayo, de cooperación con la Fiscalía Europea, es la norma que ha incorporado en el ordenamiento jurídico español el Reglamento (UE) 2017/1939 de la EPPO.'}},
{n:202, q:'Forma parte de la Oficina Principal de la Fiscalía Europea...', o:{a:'El Colegio.',b:'Las Salas Permanentes.',c:'El Fiscal General Europeo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Oficina Central de la Fiscalía Europea está compuesta por: el Colegio (formado por el Fiscal General Europeo y un Fiscal Europeo por Estado miembro participante), las Cámaras Permanentes y el Fiscal General Europeo.'}},
{n:203, q:'Forma parte de la oficina principal de la Fiscalía Europea...', o:{a:'Los Fiscales Adjuntos al Fiscal General Europeo.',b:'Los Fiscales Europeos.',c:'El Director administrativo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La oficina central de la EPPO está compuesta también por los Fiscales Europeos (uno por Estado miembro participante) y el personal administrativo, incluyendo el Director administrativo.'}},
{n:204, q:'Forma parte del Colegio de la Oficina Principal de la Fiscalía Europea...', o:{a:'El Fiscal General Europeo.',b:'Un Fiscal Europeo por cada estado miembro.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El Colegio de la EPPO está formado por el Fiscal General Europeo y un Fiscal Europeo por cada Estado miembro participante.'}},
{n:205, q:'En la Fiscalía Europea, el nivel descentralizado está integrado...', o:{a:'Por los Fiscales de Sala del Tribunal Supremo de cada estado miembro.',b:'Por los Fiscales Europeos delegados, que estarán establecidos en los estados miembros.',c:'Por los Fiscales Generales Adjuntos del Fiscal General Europeo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El nivel descentralizado de la EPPO está integrado por los Fiscales Europeos Delegados, que ejercen sus funciones desde los Estados miembros participantes.'}},
{n:206, q:'Los Fiscales Europeos delegados son competentes, en el territorio del Estado Español, para investigar y ejercer la acusación por los delitos de ...', o:{a:'Delitos contra la Hacienda de la Unión no referidos a impuestos directos nacionales tipificados en el artículo 306 del Código Penal.',b:'Delitos contra la Hacienda de la Unión no referidos a impuestos directos nacionales tipificados en el artículo 309 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Los Fiscales Europeos Delegados en España son competentes para investigar delitos contra la Hacienda de la UE no referidos a impuestos directos nacionales, tipificados en el art.306 del Código Penal.'}},
{n:207, q:'Los Fiscales Europeos delegados son competentes, en el territorio del Estado Español, para investigar y ejercer la acusación por los delitos de ...', o:{a:'Defraudación de subvenciones y ayudas europeas del artículo 308 del Código Penal.',b:'Defraudaciones a la Seguridad social del artículo 307 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Los Fiscales Europeos Delegados en España tienen competencia para investigar las defraudaciones de subvenciones y ayudas europeas tipificadas en el art.308 del Código Penal.'}},
{n:208, q:'Los Fiscales Europeos delegados son competentes, en el territorio del Estado Español, para investigar y ejercer la acusación por los delitos de ...', o:{a:'Delitos contra los derechos de los trabajadores que afecten a bienes procedentes de los delitos que perjudiquen los intereses financieros de la Unión.',b:'Delitos de blanqueo de capitales que afecten a bienes procedentes de los delitos que perjudiquen los intereses financieros de la Unión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Los Fiscales Europeos Delegados en España tienen competencia para investigar delitos de blanqueo de capitales procedentes de delitos que perjudiquen los intereses financieros de la Unión.'}},
{n:209, q:'Los Fiscales Europeos delegados son competentes, en el territorio del Estado Español, para investigar y ejercer la acusación por los delitos de ...', o:{a:'Delitos de prevaricación que perjudiquen o puedan perjudicar los intereses financieros de la Unión.',b:'Delitos de cohecho que perjudiquen o puedan perjudicar los intereses financieros de la Unión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Los Fiscales Europeos Delegados son competentes para investigar delitos de cohecho que perjudiquen los intereses financieros de la UE.'}},
{n:210, q:'Los Fiscales Europeos delegados son competentes, en el territorio del Estado Español, para investigar y ejercer la acusación por los delitos de ...', o:{a:'Malversación, cuando perjudique de cualquier manera los intereses financieros de la Unión.',b:'Participación criminal (delito del artículo 570 Bis del Código Penal) cuando su actividad principal sea la comisión de alguno de los delitos a los que hace referencia la Ley Orgánica 9/2021.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Los Fiscales Europeos Delegados tienen competencia para investigar tanto la malversación que perjudique los intereses financieros de la UE como la participación criminal en organizaciones dedicadas a cometer los delitos previstos en la LO 9/2021.'}},
{n:211, q:'En el ejercicio de sus funciones, los Fiscales Europeos delegados ...', o:{a:'Pueden dar instrucciones a los funcionarios de la Policía Judicial.',b:'Pueden dar instrucciones a los miembros del Ministerio Fiscal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Los Fiscales Europeos Delegados pueden dar instrucciones a los funcionarios de la Policía Judicial en el ejercicio de sus funciones de investigación de los delitos de la competencia de la EPPO.'}},
];
